 d=o.last_depth[cam]; print('depth percentiles',np.percentile(d[d>0],[0,10,50,90,100]))
# transform pixels to world using metric depth
def world(cam,u,v):
 c=o.meta['cameras'][cam]; K=np.array(c['intrinsic_cv']); E=np.array(c['extrinsic_cv']); d=o.last_depth[cam][int(round(v)),int(round(u))]
 pix=np.array([u,v,1.]); pc=np.linalg.solve(K,pix)*d
 return d, np.linalg.solve(E[:,:3],pc-E[:,3])
for uv in [(256,512),(54,50),(458,974),(377,193),(389,193),(377,204),(389,204),(377,215),(389,215),(377,226),(389,226),(377,237),(389,237)]:
