z=np.load('/app/output/stroke_plan.npz',allow_pickle=True); ss=list(z['strokes']); t=z['target'];N=t.size
fps=[]
for s in ss:fps.append(ps.capsule(s['a'],s['b'],float(s['radius'])))
def evalorder(order):
 cur=np.full(N,10,np.uint8)
 ix={c:[i for i,s in enumerate(ss) if int(s['color'])==c] for c in range(1,11)}
 for c in order:
  for i in ix[c]:cur[fps[i]]=c-1
 target=t.ravel();paint=target!=10;drawn=cur!=10
